export const ITERATE_IMPROVE_ACTIVITIES = [
{n:1,type:"mcq",micro:"Apa itu iterasi",q:"'Iterasi' (mengulang untuk memperbaiki) berarti...",options:["Mencoba sesuatu, melihat hasilnya, memperbaiki, lalu mencoba lagi, berulang-ulang","Mencoba sesuatu satu kali saja lalu menerima apa pun hasilnya tanpa pernah mengubahnya lagi","Membuat rencana yang sempurna lebih dulu dan menunda mencoba apa pun sampai semuanya yakin benar"],answer:0,explain:"Hampir semua hal baik, dari sepeda hingga resep masakan, jadi baik melalui banyak putaran perbaikan kecil.",hint:"Coba-lihat-perbaiki berulang, atau coba sekali saja?"},
{n:2,type:"mcq",micro:"Siklus perbaikan",q:"Urutan dasar satu putaran perbaikan:",options:["Amati → menyerah","Coba → amati hasilnya → cari apa yang bisa lebih baik → ubah → coba lagi","Ubah → berhenti → lupakan"],answer:1,explain:"Tiap putaran memberi informasi baru yang dipakai untuk putaran berikutnya. Itulah cara kemajuan terjadi.",hint:"Coba-amati-ubah-coba lagi, atau ubah lalu berhenti?"},
{n:3,type:"mcq",micro:"Gagal sebagai informasi",q:"Ketika percobaan tidak berhasil, cara pandang yang berguna:",options:["'Aku memang tidak berbakat dalam hal ini, jadi sebaiknya aku berhenti mencoba mulai sekarang.'","'Hasil percobaan yang gagal itu tidak berarti apa-apa, jadi tidak perlu dipikirkan lagi sama sekali.'","'Sekarang aku tahu satu cara yang tidak jalan & kenapa, ini petunjuk untuk percobaan berikutnya'"],answer:2,explain:"Percobaan yang 'gagal' menyingkirkan satu kemungkinan & sering menunjukkan arah yang lebih baik.",hint:"Petunjuk untuk berikutnya, atau tanda berhenti?"},
{n:4,type:"mcq",micro:"Versi",q:"Menyebut hasil kerjamu sebagai 'versi 1', 'versi 2', dst membantu karena...",options:["Mengingatkan bahwa ini belum final & wajar diperbaiki, mengurangi rasa takut salah","Membuat pekerjaan terlihat lebih banyak","Tidak ada gunanya"],answer:0,explain:"'Versi 1' terdengar seperti awal, bukan penilaian akhir. Ini melonggarkan tekanan untuk langsung sempurna.",hint:"Mengurangi takut salah, atau sekadar terlihat banyak?"},
{n:5,type:"mcq",micro:"Perbaikan kecil",q:"Memperbaiki satu hal kecil tiap putaran lebih baik daripada mengubah banyak hal sekaligus karena...",options:["Mengubah banyak hal sekaligus itu tidak mungkin dilakukan karena akan membuat hasilnya kacau semuanya","Kamu bisa tahu perubahan mana yang membuat hasil lebih baik atau lebih buruk","Perubahan kecil selalu lebih penting daripada perubahan besar, apa pun masalah yang sedang dihadapi"],answer:1,explain:"Kalau kamu mengubah 5 hal & hasilnya membaik, kamu tidak tahu perubahan mana yang berjasa. Ubah sedikit, amati, pelajari.",hint:"Bisa tahu penyebabnya, atau perubahan kecil selalu lebih penting?"},
{n:6,type:"mcq",micro:"Mengamati hasil",q:"Agar bisa memperbaiki, kita perlu...",options:["Menebak hasilnya saja dari perasaan kita tanpa memeriksa kenyataan yang sebenarnya terjadi di lapangan","Percaya sepenuhnya bahwa hasilnya pasti sudah bagus tanpa perlu dilihat atau dicoba oleh orang lain","Cara melihat hasilnya dengan jelas: apa yang berhasil, apa yang tidak, seberapa jauh dari yang diinginkan"],answer:2,explain:"Perbaikan butuh umpan balik. Tanpa melihat hasil dengan jujur, kita tidak tahu apa yang perlu diubah.",hint:"Melihat hasil dengan jelas, atau menebak?"},
{n:7,type:"mcq",micro:"Coba dulu, sempurnakan nanti",q:"Untuk sesuatu yang belum pernah kamu lakukan, pendekatan yang lebih efektif:",options:["Buat percobaan pertama yang kasar & cepat, lalu perbaiki dari apa yang kamu pelajari","Tunggu sampai kamu sudah yakin sepenuhnya bisa melakukannya dengan sempurna baru kemudian mulai mencoba","Minta orang lain saja yang melakukannya lebih dulu, lalu kamu menirunya setelah semuanya terlihat berhasil"],answer:0,explain:"Menunggu 'siap' sering berarti tidak pernah mulai. Percobaan kasar mengajari apa yang sebenarnya dibutuhkan.",hint:"Coba kasar lalu perbaiki, atau tunggu sampai yakin sempurna?"},
{n:8,type:"mcq",micro:"Contoh iterasi sehari-hari",q:"Manakah contoh iterasi dalam kehidupan sehari-hari?",options:["Orang yang tidak pernah membuat teh sama sekali sehingga tidak tahu seberapa manis rasanya nanti","Membuat teh lalu menyesuaikan takaran gula tiap kali sampai pas","Membuat teh sekali saja dengan takaran yang sama dan tidak pernah mengubah apa pun sesudah itu"],answer:1,explain:"Menyesuaikan resep, rute ke sekolah, cara belajar, semua adalah iterasi: mencoba, menilai, memperbaiki.",hint:"Menyesuaikan tiap kali, atau tidak pernah mengubah?"},
{n:9,type:"order",micro:"Satu putaran iterasi",q:"Urutkan langkah satu putaran 'uji coba, gagal, perbaiki'.",items:["Tentukan apa yang kamu harapkan terjadi","Coba versi yang ada","Bandingkan hasil nyata dengan harapan: apa yang cocok, apa yang meleset","Ubah satu atau dua hal berdasarkan temuan, lalu ulangi"],answer:[0,1,2,3],explain:"Harapan → coba → bandingkan → ubah & ulangi. Menuliskan harapan lebih dulu membuat kita bisa melihat di mana dugaan kita keliru.",hint:"Menuliskan harapan sebelum atau sesudah mencoba?"},
{n:10,type:"mcq",micro:"Gagal cepat, gagal murah",q:"'Gagal cepat, gagal murah' berarti...",options:["Sengaja membuat semua hal gagal supaya kita terbiasa dengan rasa gagal dan tidak takut lagi nanti","Gagal itu adalah tujuan utama dari setiap percobaan, bukan sekadar bagian dari proses belajar","Membuat percobaan kecil & cepat sehingga kalau salah, kerugiannya sedikit & pelajarannya datang cepat"],answer:2,explain:"Lebih baik menemukan masalah pada percobaan 30 menit daripada pada proyek 3 minggu. Kecil & cepat = aman untuk salah.",hint:"Percobaan kecil agar salah jadi murah, atau sengaja gagal?"},
{n:11,type:"tf",micro:"Kegagalan pertama itu wajar",q:"Benar atau Salah: Wajar jika percobaan pertama sebuah ide baru tidak berhasil; itu bagian normal dari proses, bukan tanda kamu tidak mampu.",answer:true,explain:"Hampir tidak ada hal berharga yang berhasil di percobaan pertama. Yang membedakan adalah kesediaan mencoba lagi dengan perbaikan.",hint:"Bagian normal proses, atau tanda tidak mampu?"},
{n:12,type:"tf",micro:"Satu percobaan cukup?",q:"Benar atau Salah: Kalau sebuah ide tidak berhasil di percobaan pertama, itu bukti kuat bahwa idenya buruk & harus dibuang.",answer:false,explain:"Sebaliknya, percobaan pertama sering gagal karena detail pelaksanaan, bukan karena ide dasarnya salah. Perbaiki & coba lagi sebelum menyimpulkan.",hint:"Gagal sekali = ide buruk, atau perlu beberapa putaran?"},
{n:13,type:"mcq",micro:"Catatan percobaan",q:"Kenapa berguna mencatat tiap percobaan (apa yang dicoba, hasilnya, apa yang diubah)?",options:["Supaya tidak mengulang percobaan yang sama & bisa melihat pola kemajuan","Supaya kita terlihat rajin & teliti di mata guru serta teman-teman yang sedang melihat pekerjaan kita","Tidak berguna sama sekali karena semua percobaan cukup diingat saja di dalam kepala sampai selesai"],answer:0,explain:"Tanpa catatan, kita mudah lupa 'sudah coba cara itu' & mengulang. Catatan mengubah coba-coba jadi belajar terstruktur.",hint:"Menghindari pengulangan & melihat pola, atau terlihat rajin?"},
{n:14,type:"mcq",micro:"Perbaikan vs kesempurnaan",q:"Tujuan tiap putaran iterasi:",options:["Membuat versi berikutnya sama saja dengan versi sebelumnya supaya hasilnya stabil dan bisa diandalkan","Membuat versi berikutnya sedikit lebih baik dari sebelumnya, bukan langsung sempurna","Langsung mencapai hasil yang sempurna pada putaran pertama tanpa perlu mengulang atau memperbaiki"],answer:1,explain:"'Lebih baik dari kemarin' adalah target yang bisa dicapai tiap putaran. 'Sempurna sekarang' sering melumpuhkan.",hint:"Sedikit lebih baik tiap kali, atau sempurna sekaligus?"},
{n:15,type:"mcq",micro:"Umpan balik mempercepat",q:"Mendapat umpan balik dari orang lain di antara putaran membantu karena...",options:["Selalu memperlambat","Membuat kita ragu tanpa manfaat","Mereka melihat masalah & peluang yang kita lewatkan, mempercepat perbaikan"],answer:2,explain:"Iterasi sendirian bisa berputar di titik buta yang sama. Mata luar memberi arah baru.",hint:"Mempercepat perbaikan, atau memperlambat?"},
{n:16,type:"tf",micro:"Iterasi butuh keberanian",q:"Benar atau Salah: Menunjukkan versi yang belum jadi ke orang lain hanya merugikan; lebih baik menyembunyikan pekerjaan sampai sempurna.",answer:false,explain:"Sebaliknya, menyembunyikan pekerjaan sampai 'sempurna' menghilangkan kesempatan memperbaiki lebih awal. Berani terlihat belum jadi & menerima kritik butuh keberanian, tapi mempercepat kita menjadi lebih baik.",hint:"Butuh keberanian & mempercepat, atau lebih baik disembunyikan?"},
{n:17,type:"mcq",micro:"Belajar dari yang berhasil juga",q:"Selain memperhatikan yang gagal, iterasi yang baik juga...",options:["Memperhatikan bagian yang BERHASIL agar tidak sengaja dihilangkan di versi berikutnya","Hanya berfokus pada kegagalan saja supaya semua kekurangan bisa segera ditemukan dan diperbaiki","Mengubah semua bagian termasuk yang sudah bagus supaya versi barunya benar-benar berbeda dari awal"],answer:0,explain:"'Bagian ini bagus, pertahankan' sama pentingnya dengan 'bagian ini perlu diperbaiki'. Iterasi bukan hanya menambal.",hint:"Jaga yang berhasil juga, atau ubah semuanya?"},
{n:18,type:"mcq",micro:"Iterasi & tenggat",q:"Kalau ada tenggat, kapan sebaiknya percobaan pertama selesai?",options:["Setelah tenggat lewat","Seawal mungkin, supaya ada waktu untuk minimal satu atau dua putaran perbaikan","Di hari terakhir"],answer:1,explain:"Nilai iterasi ada di putaran perbaikan. Percobaan pertama di menit terakhir tidak sempat memberi manfaat itu.",hint:"Seawal mungkin, atau di hari terakhir?"},
{n:19,type:"mcq",micro:"Perbaikan berdasarkan bukti",q:"Saat memutuskan apa yang diubah di versi berikutnya, dasar terbaik:",options:["Perasaan hari itu","Apa yang paling mudah diubah","Apa yang benar-benar terjadi saat diuji (pengamatan), bukan hanya tebakan atau selera"],answer:2,explain:"Perbaikan yang berdasarkan bukti nyata ('3 orang tersandung di bagian ini') lebih tepat sasaran daripada tebakan.",hint:"Pengamatan nyata, atau tebakan / kemudahan?"},
{n:20,type:"open",micro:"Rencana iterasi kecil",q:"Pilih satu hal yang ingin kamu perbaiki (mis. cara menghafal kosakata, rutinitas pagi supaya tidak telat, cara menata meja belajar). Tulis: (a) versi 1 (apa yang kamu lakukan sekarang), (b) apa yang akan kamu amati untuk tahu berhasil/tidak, (c) satu perubahan kecil untuk versi 2, (d) kapan kamu akan menilai & memutuskan perubahan berikutnya.",explain:"Jawaban baik: versi 1 dijelaskan cukup detail untuk jadi pembanding, hal yang diamati bisa diukur (jam keluar, jumlah hari tepat waktu), satu perubahan kecil yang jelas (bukan 'berusaha lebih rajin'), & titik penilaian yang konkret dengan rencana langkah berikutnya berdasar hasil.",hint:"Perubahan untuk versi 2 harus satu hal spesifik yang bisa kamu lakukan, bukan tekad umum.",sample:"Hal yang diperbaiki: rutinitas pagi supaya tidak telat ke sekolah. (a) Versi 1: aku bangun jam 05.30 saat alarm bunyi (sering ditunda 2-3 kali), lalu buru-buru mandi, sarapan, & menyiapkan tas, sering baru selesai jam 06.20 & sampai sekolah mepet. (b) Yang diamati: jam berapa aku benar-benar keluar rumah tiap hari, & berapa kali seminggu aku sampai sebelum bel. (c) Perubahan kecil untuk versi 2: menyiapkan tas & seragam malam sebelumnya, jadi pagi tinggal mandi & sarapan. (d) Menilai: setelah 5 hari sekolah, aku lihat catatan jam keluar rumah. Kalau rata-rata maju 10 menit atau lebih & aku tidak pernah telat, aku pertahankan & tambah satu perubahan lagi (mis. alarm dipindah jauh dari tempat tidur supaya tidak bisa ditunda). Kalau belum membaik, aku cari tahu bagian mana yang masih memakan waktu paling lama & ubah itu."},
{n:21,type:"classify",micro:"Sikap yang mendukung vs menghambat iterasi",q:"Kelompokkan tiap sikap ke 'Mendukung iterasi' atau 'Menghambat iterasi'.",items:["'Versi ini belum bagus, apa satu hal yang bisa kuperbaiki?'","'Kalau tidak langsung berhasil, berarti aku memang tidak bisa.'","'Coba kutunjukkan ke teman untuk dikritik sebelum lanjut.'","'Sudah kubuat, tidak mau kuubah lagi apa pun kata orang.'"],groups:["Mendukung iterasi","Menghambat iterasi"],answer:{"Mendukung iterasi":["'Versi ini belum bagus, apa satu hal yang bisa kuperbaiki?'","'Coba kutunjukkan ke teman untuk dikritik sebelum lanjut.'"],"Menghambat iterasi":["'Kalau tidak langsung berhasil, berarti aku memang tidak bisa.'","'Sudah kubuat, tidak mau kuubah lagi apa pun kata orang.'"]},explain:"Mendukung: melihat versi sebagai bisa diperbaiki, mengundang kritik. Menghambat: menyimpulkan diri tidak mampu, menolak perubahan.",hint:"Terbuka untuk memperbaiki, atau menutup diri?"},
{n:22,type:"mcq",micro:"Pola pikir bertumbuh",q:"'Pola pikir bertumbuh' dalam konteks iterasi berarti percaya bahwa...",options:["Kemampuan bisa berkembang lewat usaha & belajar dari kesalahan, bukan sesuatu yang tetap sejak lahir","Semua orang sebenarnya punya kemampuan yang sama sehingga hasil yang berbeda hanya soal keberuntungan","Kesalahan harus dihindari dengan segala cara karena kesalahan menunjukkan bahwa kita tidak mampu"],answer:0,explain:"Kalau kita percaya kemampuan bisa tumbuh, kegagalan jadi 'belum bisa' bukan 'tidak akan pernah bisa', & iterasi jadi masuk akal.",hint:"Kemampuan bisa tumbuh lewat usaha, atau tetap sejak lahir?"},
{n:23,type:"mcq",micro:"Kesalahan vs eksperimen",q:"Beda 'kesalahan yang bisa dicegah' dengan 'kegagalan eksperimen':",options:["Eksperimen tidak pernah gagal","Kesalahan yang bisa dicegah: kita sudah tahu cara benarnya tapi lalai. Kegagalan eksperimen: kita memang belum tahu & sedang mencari","Keduanya sama"],answer:1,explain:"Kegagalan eksperimen (mencoba hal baru untuk belajar) berharga & wajar. Kesalahan karena lalai pada hal yang sudah diketahui perlu dikurangi.",hint:"Sama saja, atau satu karena lalai & satu karena mencari?"},
{n:24,type:"mcq",micro:"Mengukur kemajuan",q:"Agar tahu apakah iterasi kita membuat kemajuan, berguna...",options:["Mengandalkan perasaan 'kayaknya sudah lebih baik' saja tanpa mencatat angka atau bukti apa pun","Tidak perlu ukuran apa pun karena kemajuan pasti terlihat sendiri dengan jelas bagi semua orang","Menetapkan satu atau dua ukuran sederhana & mencatatnya tiap putaran"],answer:2,explain:"Ukuran (waktu selesai, jumlah kesalahan, berapa orang paham) menunjukkan kemajuan atau kemunduran yang tidak selalu terasa.",hint:"Ukuran sederhana yang dicatat, atau mengandalkan perasaan?"},
{n:25,type:"mcq",micro:"Umpan balik yang berguna untuk iterasi",q:"Jenis umpan balik yang paling membantu putaran berikutnya:",options:["Spesifik & tentang hal yang bisa diubah ('bagian awal terlalu panjang')","Umum & tentang pribadi orangnya, misalnya 'kamu memang kurang teliti dan sering sembrono'","Hanya pujian yang menyenangkan tanpa detail apa pun tentang bagian mana yang sudah bagus atau kurang"],answer:0,explain:"Umpan balik yang menunjuk bagian tertentu & menyarankan arah bisa langsung dipakai. Yang umum atau menyerang pribadi tidak.",hint:"Spesifik & bisa ditindaklanjuti, atau umum & menyerang pribadi?"},
{n:26,type:"mcq",micro:"Retrospektif",q:"'Retrospektif' setelah sebuah putaran atau proyek berarti...",options:["Merayakan keberhasilan bersama-sama tanpa membahas apa pun yang berjalan baik atau kurang baik","Meninjau bersama: apa yang berjalan baik, apa yang tidak, apa yang akan diubah lain kali","Menyalahkan siapa yang membuat kesalahan supaya orang itu lebih berhati-hati pada proyek berikutnya"],answer:1,explain:"Retrospektif mengubah pengalaman jadi pelajaran yang jelas. Fokusnya perbaikan sistem & cara kerja, bukan mencari kambing hitam.",hint:"Meninjau untuk perbaikan, atau mencari yang disalahkan?"},
{n:27,type:"tf",micro:"Iterasi lambat itu tetap iterasi",q:"Benar atau Salah: Kalau kamu hanya bisa melakukan satu putaran perbaikan, lebih baik tidak usah karena satu putaran tidak berarti apa-apa.",answer:false,explain:"Sebaliknya, satu putaran perbaikan berdasarkan umpan balik nyata biasanya membuat perbedaan besar dibanding versi pertama yang tidak pernah ditinjau.",hint:"Satu putaran tetap berharga, atau percuma kalau tidak banyak?"},
{n:28,type:"tf",micro:"Semua kegagalan sama berharganya?",q:"Benar atau Salah: Semua kegagalan sama berharganya sebagai pelajaran, tidak peduli apakah kita merefleksikannya atau tidak.",answer:false,explain:"Sebaliknya, kegagalan hanya jadi pelajaran kalau kita meluangkan waktu memeriksa kenapa itu terjadi & apa yang akan diubah. Gagal tanpa refleksi mudah terulang.",hint:"Otomatis jadi pelajaran, atau perlu direfleksikan?"},
{n:29,type:"mcq",micro:"Iterasi & rasa memiliki",q:"Kelompok yang bersama-sama melakukan putaran perbaikan cenderung...",options:["Bosan dan kehilangan minat karena melihat pekerjaan yang sama diulang-ulang berkali-kali oleh kelompok","Selalu berdebat lebih banyak karena setiap anggota punya pendapat berbeda tentang perbaikan yang perlu","Lebih memahami & mendukung hasil akhir karena melihat bagaimana ia berkembang"],answer:2,explain:"Menyaksikan sebuah ide tumbuh lewat perbaikan membangun keterikatan & pemahaman bersama.",hint:"Lebih memahami & mendukung, atau bosan?"},
{n:30,type:"order",micro:"Menyiapkan iterasi terukur",q:"Urutkan langkah menyiapkan proses perbaikan yang terukur.",items:["Tentukan tujuan: seperti apa 'lebih baik' yang kita inginkan","Pilih 1-2 ukuran sederhana yang mencerminkan tujuan itu","Catat ukuran untuk versi saat ini sebagai titik awal","Setelah tiap perubahan, ukur lagi & bandingkan dengan titik awal"],answer:[0,1,2,3],explain:"Tujuan → pilih ukuran → catat titik awal → ukur ulang tiap putaran. Tanpa titik awal, kita tidak tahu apakah membaik.",hint:"Mencatat titik awal sebelum atau sesudah perubahan pertama?"},
{n:31,type:"mcq",micro:"Iterasi vs perfeksionisme",q:"Bagaimana iterasi membantu orang yang takut hasilnya tidak sempurna?",options:["Memecah 'harus sempurna' jadi 'buat versi kasar dulu, perbaiki bertahap', sehingga bisa mulai","Menghapus standar mutu sepenuhnya supaya tidak ada lagi yang perlu ditakutkan atau diperbaiki","Membuat semuanya selesai lebih lambat karena harus mengulang pekerjaan yang sama berkali-kali"],answer:0,explain:"Perfeksionisme sering melumpuhkan di awal. Iterasi memberi izin memulai dengan yang belum sempurna & memperbaikinya kemudian.",hint:"Izin memulai dengan kasar lalu memperbaiki, atau menghapus standar?"},
{n:32,type:"tf",micro:"Perbaikan bisa membuat lebih buruk",q:"Benar atau Salah: Kadang sebuah perubahan yang dimaksudkan memperbaiki justru membuat hasil lebih buruk, & itu juga informasi berguna.",answer:true,explain:"'Perubahan X membuat lebih buruk' memberi tahu kita untuk mengembalikannya & mencoba arah lain. Mencatat perubahan membuat ini bisa diketahui.",hint:"Bisa jadi lebih buruk & itu informasi, atau perubahan selalu memperbaiki?"},
{n:33,type:"mcq",micro:"Iterasi pada keterampilan",q:"Belajar keterampilan (menggambar, bermain alat musik, berpidato) adalah iterasi karena...",options:["Keterampilan tidak bisa diperbaiki, orang hanya berbakat sejak lahir atau tidak sama sekali","Kita berlatih, melihat/mendengar hasilnya, menyesuaikan, & mengulang, ribuan kali","Kita langsung bisa melakukannya dengan sempurna setelah membaca penjelasan caranya satu kali saja"],answer:1,explain:"Setiap latihan adalah satu putaran: coba, dengar/lihat hasilnya, sesuaikan. Kemajuan datang dari banyak putaran, bukan bakat instan.",hint:"Latihan berulang dengan penyesuaian, atau langsung bisa?"},
{n:34,type:"mcq",micro:"Gagal di depan orang lain",q:"Saat percobaanmu gagal di depan kelompok, sikap yang membangun budaya iterasi:",options:["Malu & tidak mau mencoba lagi di depan kelompok supaya tidak mengulang kegagalan yang sama","Menyalahkan alat atau keadaan yang tidak mendukung supaya tidak ada yang mengira kita kurang mampu","'Oke, itu tidak jalan. Yang kupelajari: ... Ide untuk percobaan berikutnya: ...'"],answer:2,explain:"Menanggapi kegagalan dengan tenang & fokus pada pelajaran membuat orang lain juga berani mencoba & gagal.",hint:"Ambil pelajaran & lanjut, atau malu / menyalahkan?"},
{n:35,type:"mcq",micro:"Iterasi & waktu",q:"Menyisihkan waktu khusus untuk 'meninjau & memperbaiki' (bukan hanya 'mengerjakan') berarti...",options:["Mengakui bahwa perbaikan butuh waktu tersendiri & tidak terjadi otomatis","Membuang waktu produktif karena waktu itu seharusnya dipakai untuk mengerjakan hal yang baru saja","Hanya perlu dilakukan untuk proyek yang besar, sedangkan tugas kecil tidak memerlukan peninjauan"],answer:0,explain:"Kalau semua waktu dipakai 'maju terus', tidak ada ruang untuk mundur sejenak & melihat apa yang bisa lebih baik.",hint:"Perbaikan butuh waktu tersendiri, atau terjadi otomatis?"},
{n:36,type:"mcq",micro:"Membandingkan versi",q:"Menyimpan versi lama (tidak menimpanya) berguna karena...",options:["Tidak berguna sama sekali, sebab versi yang baru selalu lebih baik daripada versi yang sebelumnya","Kalau versi baru ternyata lebih buruk, kita bisa kembali; & kita bisa melihat kemajuan dari waktu ke waktu","Membuat tempat penyimpanan menjadi penuh tanpa alasan yang jelas dan hanya merepotkan kita saja"],answer:1,explain:"Versi baru tidak selalu lebih baik. Menyimpan yang lama adalah jaring pengaman & catatan perjalanan.",hint:"Bisa kembali & melihat kemajuan, atau versi baru selalu lebih baik?"},
{n:37,type:"tf",micro:"Iterasi mengurangi risiko",q:"Benar atau Salah: Membuat satu lompatan besar sekaligus biasanya lebih aman & efisien daripada memperbaiki lewat banyak putaran kecil.",answer:false,explain:"Sebaliknya, perubahan kecil mudah dinilai & dibatalkan kalau salah; lompatan besar sulit dievaluasi & mahal kalau meleset.",hint:"Putaran kecil lebih aman, atau lompatan besar lebih efisien?"},
{n:38,type:"mcq",micro:"Iterasi & harapan realistis",q:"Harapan yang sehat tentang berapa putaran yang dibutuhkan:",options:["Selalu tepat satu putaran saja sudah cukup untuk membuat hasil yang memuaskan semua orang","Iterasi tidak pernah selesai sehingga kita harus terus mengulang tanpa pernah menyatakan cukup","Sering lebih banyak dari yang kita kira, bersiaplah untuk beberapa putaran sebelum hasilnya memuaskan"],answer:2,explain:"Menyangka 'sekali perbaikan pasti beres' menyebabkan frustrasi. Menerima bahwa perlu beberapa putaran membuat prosesnya terasa normal.",hint:"Bersiap untuk beberapa putaran, atau selalu satu?"},
{n:39,type:"mcq",micro:"Umpan balik dari data & dari orang",q:"Sumber umpan balik untuk iterasi bisa berupa...",options:["Pengukuran (angka, waktu, jumlah), pengamatan perilaku, & pendapat orang, ketiganya saling melengkapi","Hanya pendapat orang lain saja, sebab angka dan pengamatan sering kali tidak bisa dipercaya","Hanya perasaan pembuatnya sendiri, sebab dialah yang paling mengerti seperti apa hasil terbaiknya"],answer:0,explain:"Angka menunjukkan 'apakah', pengamatan menunjukkan 'di mana', pendapat menunjukkan 'kenapa'. Bersama mereka memberi gambaran lengkap.",hint:"Gabungan angka, pengamatan, & pendapat, atau satu saja?"},
{n:40,type:"open",micro:"Merefleksikan sebuah kegagalan",q:"Ingat satu kali kamu mencoba sesuatu & tidak berhasil (proyek, lomba, cara belajar, apa pun). Tulis refleksi: (a) apa yang kamu coba & apa yang kamu harapkan, (b) apa yang sebenarnya terjadi, (c) minimal 2 kemungkinan penyebab, (d) apa yang akan kamu lakukan berbeda jika mencoba lagi, (e) apakah ini kegagalan 'eksperimen' (mencari cara baru) atau 'kesalahan yang bisa dicegah' (lalai pada yang sudah diketahui).",explain:"Jawaban baik: menceritakan harapan & kenyataan dengan jujur, minimal 2 penyebab yang masuk akal (bukan hanya 'aku kurang pintar'), rencana perubahan yang spesifik & terhubung ke penyebab, & penilaian jujur tentang jenis kegagalannya, termasuk mengakui bila ada bagian yang sebenarnya bisa dicegah.",hint:"Bagian (c) kuncinya, cari penyebab pada metode & keadaan, bukan hanya pada kemampuan diri.",sample:"(a) Yang kucoba: belajar untuk ujian Matematika dengan cara membaca ulang seluruh catatan tiga malam berturut-turut. Harapanku: karena aku sudah membaca semuanya beberapa kali, aku akan ingat & bisa mengerjakan soal. (b) Yang terjadi: saat ujian aku mengenali semua materi ('oh iya, ini pernah kubaca') tapi tidak bisa mengerjakan soal yang butuh langkah hitungan; nilaiku di bawah harapan. (c) Kemungkinan penyebab: (1) Membaca ulang membuatku merasa 'sudah paham' padahal aku tidak pernah benar-benar melatih mengerjakan soal sendiri. (2) Aku belajar larut malam & mengantuk, jadi konsentrasiku rendah. (3) Aku tidak pernah menguji diri, jadi tidak tahu bagian mana yang sebenarnya belum kukuasai. (d) Yang kulakukan berbeda: alih-alih membaca ulang, aku akan mengerjakan soal latihan tanpa melihat catatan, mengoreksi, lalu mengulang bagian yang salah; dan belajar sore, bukan larut malam. (e) Ini campuran: sebagian 'eksperimen' karena aku memang belum tahu cara belajar yang cocok untukku, tapi sebagian 'kesalahan yang bisa dicegah' karena aku sebenarnya sudah pernah diberi tahu guru bahwa latihan soal lebih penting daripada membaca ulang, & aku mengabaikannya."},
{n:41,type:"mcq",micro:"Mengubah satu variabel",q:"Kalau kamu ingin tahu apakah 'belajar sambil mendengarkan musik' membantumu, cara yang tepat:",options:["Tanya teman lalu ikuti saja jawabannya tanpa mencoba sendiri supaya tidak perlu membuang waktu","Coba beberapa sesi dengan musik & beberapa tanpa, jaga hal lain tetap sama, bandingkan hasilnya","Ubah musik, tempat, waktu, & lama belajar sekaligus lalu simpulkan mana yang paling berpengaruh"],answer:1,explain:"Mengubah satu hal saja (musik) sambil menjaga sisanya membuat kamu tahu apakah musik itu yang membuat perbedaan.",hint:"Ubah satu hal & bandingkan, atau ubah semua sekaligus?"},
{n:42,type:"mcq",micro:"Uji A/B",q:"'Uji A/B' berarti...",options:["Membuat versi A saja lalu menyerah sebelum sempat membuat versi B untuk dibandingkan dengannya","Memberi nama A & B pada satu versi yang sama supaya terlihat seolah-olah sudah dibandingkan","Membuat dua versi yang berbeda dalam satu hal, mencobanya pada situasi serupa, & melihat mana yang lebih baik"],answer:2,explain:"Mis. dua versi poster ajakan (A: banyak teks, B: sedikit teks + gambar) ditempel di lokasi berbeda, hitung mana yang lebih menarik minat.",hint:"Dua versi beda satu hal, dibandingkan, atau menyerah setelah A?"},
{n:43,type:"mcq",micro:"Catatan percobaan yang baik",q:"Isi catatan percobaan yang berguna untuk iterasi:",options:["Tanggal, apa yang dicoba, apa yang diubah dari sebelumnya, hasilnya, & ide untuk berikutnya","Hanya tulisan 'berhasil' atau 'gagal' supaya catatan singkat dan tidak memakan banyak halaman","Perasaan kita saat mencoba tanpa detail apa pun tentang apa yang dilakukan dan apa hasilnya"],answer:0,explain:"Catatan yang mencatat 'apa yang diubah' & 'hasilnya' memungkinkan kita menghubungkan perubahan dengan dampaknya.",hint:"Perubahan + hasil + ide berikutnya, atau sekadar 'berhasil/gagal'?"},
{n:44,type:"mcq",micro:"Kaizen (perbaikan terus-menerus)",q:"'Kaizen' adalah pendekatan...",options:["Membiarkan sesuatu apa adanya karena yang sudah berjalan sebaiknya tidak diubah sedikit pun lagi","Perbaikan kecil yang terus-menerus, dilakukan rutin, sehingga menumpuk jadi peningkatan besar seiring waktu","Perombakan besar-besaran yang dilakukan sekali setahun saja supaya semua orang bisa bersiap lebih dulu"],answer:1,explain:"Memperbaiki 1% tiap hari terdengar kecil, tapi dalam beberapa bulan hasilnya jauh lebih baik. Konsistensi mengalahkan lompatan.",hint:"Perbaikan kecil terus-menerus, atau perombakan besar sekali?"},
{n:45,type:"tf",micro:"Batas waktu tiap putaran",q:"Benar atau Salah: Memberi batas waktu untuk tiap putaran iterasi (mis. 'perbaiki & uji lagi dalam 2 hari') membantu menjaga momentum & mencegah terjebak menyempurnakan satu versi.",answer:true,explain:"Tanpa batas, kita bisa berbulan-bulan di satu versi. Batas waktu memaksa 'cukup baik untuk diuji lagi' & menjaga putaran tetap bergulir.",hint:"Batas waktu menjaga momentum, atau menghambat?"},
{n:46,type:"mcq",micro:"Prototipe & iterasi",q:"Hubungan prototipe dengan iterasi:",options:["Keduanya tidak berhubungan sama sekali, prototipe untuk tahap awal sedangkan iterasi hanya untuk akhir","Prototipe menggantikan kebutuhan iterasi karena versi yang sudah dibuat tidak perlu diperbaiki lagi","Prototipe adalah 'versi' yang diuji tiap putaran; iterasi adalah proses memperbaikinya dari putaran ke putaran"],answer:2,explain:"Buat prototipe → uji → temukan masalah → buat prototipe yang lebih baik. Prototipe adalah bahan, iterasi adalah mesinnya.",hint:"Prototipe = versi yang diiterasi, atau tak berhubungan?"},
{n:47,type:"mcq",micro:"Fokus perbaikan",q:"Kalau ada 8 masalah ditemukan di satu putaran, sebaiknya di putaran berikutnya...",options:["Perbaiki 2-3 yang paling penting atau paling menghambat, lalu uji lagi","Perbaiki semua delapan masalah itu sekaligus supaya putaran berikutnya langsung menghasilkan versi sempurna","Perbaiki yang paling mudah saja & abaikan yang penting supaya pekerjaan cepat selesai dan terlihat rapi"],answer:0,explain:"Memperbaiki sedikit yang paling berdampak lalu menguji lagi membuat kita tahu apakah perbaikan itu cukup, sebelum menambah lebih banyak perubahan.",hint:"Beberapa yang terpenting lalu uji, atau semua sekaligus?"},
{n:48,type:"mcq",micro:"Iterasi bersama umpan balik pengguna",q:"Cara memasukkan pengguna ke dalam siklus iterasi:",options:["Pengguna tidak perlu dilibatkan sama sekali sebab pembuat yang paling tahu apa yang terbaik bagi mereka","Setiap versi diuji ke pengguna, temuan mereka menjadi daftar perbaikan untuk versi berikutnya","Pengguna hanya dilibatkan di akhir proyek, setelah semua versi selesai dibuat dan tidak bisa diubah lagi"],answer:1,explain:"Pengguna di setiap putaran menjaga perbaikan tetap menuju kebutuhan nyata, bukan menuju selera pembuat saja.",hint:"Pengguna di tiap putaran, atau hanya di akhir?"},
{n:49,type:"mcq",micro:"Mengembalikan perubahan yang gagal",q:"Kamu mengubah sesuatu di versi 3 & hasilnya lebih buruk dari versi 2. Langkah yang tepat:",options:["Pertahankan perubahan itu karena sudah terlanjur dikerjakan dan sayang kalau harus dikembalikan lagi","Ubah lebih banyak lagi bagian lain dengan harapan hasilnya akan menjadi lebih baik pada putaran berikutnya","Kembalikan bagian itu ke seperti versi 2, catat bahwa perubahan itu tidak berhasil, coba arah lain"],answer:2,explain:"Iterasi bisa maju & mundur. Mengembalikan perubahan yang terbukti buruk adalah langkah maju, bukan kekalahan.",hint:"Kembalikan & coba arah lain, atau pertahankan / ubah lebih banyak?"},
{n:50,type:"order",micro:"Uji A/B sederhana",q:"Urutkan langkah melakukan uji A/B sederhana untuk poster ajakan kegiatan.",items:["Tentukan apa yang ingin diukur (mis. berapa siswa bertanya tentang kegiatan)","Buat dua versi poster yang berbeda dalam satu hal (mis. judul)","Tempel di dua lokasi yang mirip ramainya, dalam waktu yang sama","Hitung hasilnya untuk tiap versi & pilih yang lebih efektif untuk dikembangkan"],answer:[0,1,2,3],explain:"Tentukan ukuran → buat dua versi beda satu hal → uji di kondisi setara → bandingkan hasil. Beda satu hal saja agar tahu apa yang berpengaruh.",hint:"Menentukan apa yang diukur sebelum atau sesudah membuat kedua versi?"},
{n:51,type:"mcq",micro:"Iterasi pada tulisan",q:"Menerapkan iterasi pada karangan berarti...",options:["Menulis draf kasar, membacanya (atau meminta orang membacanya), memperbaiki bagian yang tidak jelas, mengulang","Menulis sekali saja dengan sungguh-sungguh lalu langsung mengumpulkannya tanpa dibaca ulang oleh siapa pun","Menghapus semuanya dan memulai dari nol setiap kali ada satu kalimat yang dirasa kurang bagus saja"],answer:0,explain:"Tulisan yang baik hampir selalu draf ketiga atau keempat. Tiap putaran memperjelas & merapikan.",hint:"Draf kasar lalu revisi berulang, atau sekali jadi?"},
{n:52,type:"tf",micro:"Iterasi butuh titik awal yang dicatat",q:"Benar atau Salah: Untuk tahu apakah perubahan membuat kemajuan, kita tidak perlu tahu keadaan sebelumnya; cukup merasa hasilnya membaik.",answer:false,explain:"Sebaliknya, tanpa mencatat 'versi 1 butuh 20 menit', kita tidak bisa tahu apakah 'versi 2 butuh 15 menit' adalah kemajuan atau sekadar perasaan.",hint:"Perlu titik awal yang dicatat, atau cukup merasa membaik?"},
{n:53,type:"mcq",micro:"Retrospektif tim yang aman",q:"Agar retrospektif tim menghasilkan perbaikan nyata, aturan yang penting:",options:["Hanya ketua tim yang boleh menilai pekerjaan, sedangkan anggota lain cukup mendengarkan dan mencatat","Fokus pada 'apa yang bisa kita ubah', bukan 'siapa yang salah'; semua boleh bicara jujur tanpa dihakimi","Orang yang membuat kesalahan harus minta maaf di depan semua anggota supaya tidak mengulanginya lagi"],answer:1,explain:"Retrospektif yang berubah jadi ajang menyalahkan membuat orang menyembunyikan masalah lain kali. Fokus perbaikan sistem menjaga kejujuran.",hint:"Fokus pada yang bisa diubah & aman untuk jujur, atau mencari yang salah?"},
{n:54,type:"mcq",micro:"Mempercepat putaran",q:"Cara membuat putaran iterasi lebih cepat:",options:["Buat tiap versi lebih besar & lebih lengkap supaya ujinya sekali jalan sudah menjawab banyak pertanyaan","Kurangi jumlah pengujian supaya waktu yang tersisa bisa dipakai untuk membuat versi yang lebih bagus","Buat versi yang lebih kecil/kasar sehingga cepat dibuat & cepat diuji"],answer:2,explain:"Putaran cepat = belajar cepat. Versi yang lebih kecil & fokus bisa dibuat & diuji dalam hitungan jam, bukan hari.",hint:"Versi lebih kecil & cepat, atau lebih besar & lengkap?"},
{n:55,type:"mcq",micro:"Iterasi & daftar perbaikan",q:"Menyimpan 'daftar perbaikan' selama menguji berguna karena...",options:["Semua ide perbaikan tercatat di satu tempat & bisa diprioritaskan, tidak ada yang lupa atau langsung dikerjakan tanpa dipilih","Membuat daftar yang panjang & menakutkan sehingga kelompok justru jadi enggan memperbaiki apa pun","Tidak berguna, sebab setiap perbaikan lebih baik langsung dikerjakan saja saat itu juga tanpa dipilih"],answer:0,explain:"Daftar memisahkan 'menemukan masalah' dari 'memutuskan mana yang diperbaiki dulu'. Ini menjaga fokus tiap putaran.",hint:"Kumpulkan & prioritaskan, atau kerjakan semua langsung?"},
{n:56,type:"tf",micro:"Iterasi juga untuk kebiasaan",q:"Benar atau Salah: Kebiasaan pribadi (olahraga, belajar, tidur) bisa diperbaiki dengan iterasi: coba pola tertentu seminggu, tinjau, sesuaikan, ulangi.",answer:true,explain:"Alih-alih menyerah karena 'gagal disiplin', pendekatan iteratif memperlakukan tiap minggu sebagai percobaan yang bisa dievaluasi & disesuaikan.",hint:"Kebiasaan bisa diiterasi, atau harus langsung sempurna?"},
{n:57,type:"mcq",micro:"Iterasi & standar 'cukup baik'",q:"Menetapkan 'cukup baik untuk putaran ini' berarti...",options:["Tidak pernah merasa puas dengan hasil apa pun sehingga setiap versi selalu dianggap belum layak diuji","Menentukan tingkat mutu yang layak diuji sekarang, sisanya diperbaiki di putaran berikutnya","Menerima mutu yang buruk selamanya karena putaran ini hanyalah percobaan yang tidak perlu dipikirkan"],answer:1,explain:"'Cukup baik untuk diuji' berbeda dari 'cukup baik untuk final'. Menentukan ambang ini menjaga putaran tetap bergerak.",hint:"Layak diuji sekarang, atau menerima buruk selamanya?"},
{n:58,type:"mcq",micro:"Iterasi dengan sumber daya terbatas",q:"Kalau bahan atau waktu sangat terbatas, iterasi tetap mungkin dengan...",options:["Menyerah saja karena iterasi membutuhkan banyak bahan & waktu yang tidak mungkin kita sediakan","Hanya membuat satu versi yang besar & lengkap supaya bahan tidak terbuang untuk membuat versi yang lain","Menguji lewat sketsa, simulasi, atau versi mini, sehingga tiap putaran nyaris tidak memakai sumber daya"],answer:2,explain:"Putaran murah (di kertas, dalam pikiran, skala mini) memungkinkan banyak perbaikan sebelum menyentuh bahan yang mahal.",hint:"Putaran murah lewat sketsa/mini, atau menyerah?"},
{n:59,type:"mcq",micro:"Menghentikan perubahan yang tidak perlu",q:"Tanda sebuah bagian TIDAK perlu diubah di putaran ini:",options:["Pengujian menunjukkan bagian itu bekerja baik & tidak ada keluhan tentangnya","Kamu sudah bosan melihat bagian itu sehingga ingin segera berpindah ke bagian lain yang lebih baru","Kamu belum pernah mengubahnya sejak versi pertama sehingga pasti sudah waktunya diganti dengan yang baru"],answer:0,explain:"'Kalau tidak rusak, jangan diperbaiki' berlaku dalam iterasi juga. Ubah yang bermasalah, jaga yang berhasil.",hint:"Bekerja baik & tanpa keluhan, atau sekadar bosan?"},
{n:60,type:"open",micro:"Rancang satu siklus perbaikan lengkap",q:"Pilih sesuatu yang sedang kamu kerjakan atau ingin perbaiki. Rancang satu siklus lengkap: (a) versi/keadaan saat ini & 1-2 ukuran titik awal, (b) 1 perubahan yang akan kamu uji & alasannya (berdasar bukti/pengamatan, bukan tebakan acak), (c) bagaimana kamu menjaga hal lain tetap sama, (d) bagaimana & kapan mengukur ulang, (e) tiga kemungkinan hasil (membaik/sama/memburuk) & apa langkahmu untuk masing-masing.",explain:"Jawaban baik: keadaan awal dengan ukuran yang bisa dihitung, satu perubahan yang didasari pengamatan nyata (bukan 'coba saja'), usaha nyata menjaga variabel lain tetap, waktu & cara pengukuran ulang yang jelas, & tiga cabang tindakan yang masuk akal & berbeda untuk tiap kemungkinan hasil.",hint:"Bagian (c) sering dilupakan, sebutkan hal-hal yang kamu sengaja jaga tetap sama supaya hasilnya bisa dipercaya.",sample:"Hal yang dikerjakan: latihan lari 12 menit untuk tes kebugaran sekolah. (a) Keadaan saat ini: aku lari lalu jalan bergantian tanpa aturan, jarak yang kutempuh dalam 12 menit sekitar 1,6 km, & aku sering berhenti karena napas berat di menit ke-4. Ukuran titik awal: jarak dalam 12 menit (1,6 km), & di menit ke berapa aku pertama kali berhenti (menit 4). (b) Perubahan yang diuji: memakai pola lari-jalan terjadwal, lari 2 menit lalu jalan cepat 1 menit, diulang. Alasannya: aku amati bahwa aku selalu 'kehabisan' karena memulai terlalu cepat lalu terpaksa berhenti lama; pola terjadwal harusnya membuat tenaga lebih merata. (c) Menjaga hal lain sama: latihan di lintasan & waktu yang sama (sore), setelah istirahat yang sama, memakai sepatu yang sama, tidak mengubah pola makan. (d) Mengukur ulang: setelah 6 sesi (dua minggu), ukur lagi jarak dalam 12 menit & menit pertama berhenti, di kondisi yang sama. (e) Kemungkinan hasil: MEMBAIK (jarak bertambah atau berhenti lebih lambat), lanjutkan pola ini & tambah durasi lari jadi 3 menit; SAMA, pertahankan pola tapi ubah satu hal lain, mungkin pemanasan lebih lama atau minum lebih cukup sebelum lari; MEMBURUK, kembali ke cara lama & cari tahu apakah pola jadwalnya terlalu berat, mungkin coba lari 1 menit-jalan 1 menit dulu."},
{n:61,type:"mcq",micro:"Kapan berhenti beriterasi",q:"Waktu yang wajar berhenti memperbaiki & menyatakan sesuatu 'selesai untuk sekarang':",options:["Setelah tepat satu putaran selesai, karena satu putaran sudah cukup untuk memastikan semuanya beres","Ketika putaran terakhir hanya menghasilkan perbaikan sangat kecil & sudah cukup baik untuk tujuannya","Tidak pernah, sebab selalu ada saja bagian yang masih bisa diperbaiki sehingga tidak boleh berhenti"],answer:1,explain:"'Selalu ada yang bisa diperbaiki' benar, tapi pada titik tertentu waktu lebih baik dipakai untuk hal lain. Kenali 'imbal hasil yang mengecil'.",hint:"Saat perbaikan jadi sangat kecil & sudah cukup, atau tidak pernah?"},
{n:62,type:"mcq",micro:"Over-iterating (memperbaiki berlebihan)",q:"Tanda kamu terlalu lama memperbaiki satu hal:",options:["Kamu menguji setiap versi kepada pengguna nyata & mencatat temuan mereka dengan rapi dan teratur","Kamu berhenti memperbaiki setelah hasilnya memuaskan dan sesuai dengan tujuan yang sudah ditetapkan","Kamu terus mengubah detail kecil, tenggat terlewat, & bagian lain terabaikan, padahal hasilnya sudah cukup baik"],answer:2,explain:"Perfeksionisme bisa menyamar sebagai 'iterasi rajin'. Kalau perbaikan tidak lagi berarti & mengorbankan hal lain, saatnya berhenti.",hint:"Detail kecil tanpa henti & mengorbankan hal lain, atau berhenti saat cukup?"},
{n:63,type:"mcq",micro:"Kegagalan yang tidak boleh diulang",q:"Beberapa kegagalan (mis. yang membahayakan keselamatan, melanggar aturan penting, atau menyakiti orang) berbeda karena...",options:["Kita tidak boleh 'mencoba lagi & lihat', kita harus mencegahnya sepenuhnya dengan hati-hati sejak awal","Sama seperti kegagalan lain, boleh dicoba lagi saja sampai akhirnya ketemu cara yang benar-benar tepat","Tidak perlu dipikirkan sama sekali, sebab semua kegagalan pasti bisa diperbaiki pada percobaan berikutnya"],answer:0,explain:"'Gagal cepat, gagal murah' berlaku untuk eksperimen yang aman. Untuk hal berisiko tinggi, pencegahan & kehati-hatian mengalahkan coba-coba.",hint:"Cegah sepenuhnya sejak awal, atau coba lagi seperti biasa?"},
{n:64,type:"tf",micro:"Belajar dari kegagalan orang lain",q:"Benar atau Salah: Mempelajari kegagalan orang lain tidak membantu; setiap orang harus mengalami kegagalannya sendiri untuk benar-benar belajar.",answer:false,explain:"Sebaliknya, tidak semua pelajaran harus dibayar dengan kegagalan sendiri. Bertanya 'siapa yang pernah mencoba ini & apa yang mereka temukan' bisa menghemat banyak putaran.",hint:"Bisa belajar dari kegagalan orang lain, atau harus gagal sendiri dulu?"},
{n:65,type:"mcq",micro:"Iterasi menuju arah yang salah",q:"Bahaya memperbaiki terus tanpa sesekali mundur & bertanya 'apakah tujuannya masih benar?':",options:["Iterasi menjadi terlalu cepat sehingga kita tidak sempat menikmati hasil dari setiap putaran perbaikan","Kita bisa menjadi sangat baik dalam menyelesaikan masalah yang salah","Tidak ada bahayanya sama sekali, sebab perbaikan yang terus dilakukan selalu menghasilkan hal yang baik"],answer:1,explain:"Iterasi memperbaiki 'bagaimana'. Sesekali perlu memeriksa 'apa' & 'kenapa' juga, jangan sampai memoles jalan menuju tempat yang salah.",hint:"Bisa jago menyelesaikan masalah yang salah, atau tidak ada bahaya?"},
{n:66,type:"mcq",micro:"Menafsirkan hasil yang bercampur",q:"Setelah sebuah perubahan, sebagian ukuran membaik & sebagian memburuk. Sikap yang tepat:",options:["Anggap perubahan itu berhasil karena sudah ada ukuran yang membaik, dan abaikan ukuran yang memburuk","Anggap perubahan itu gagal karena ada ukuran yang memburuk, lalu batalkan semuanya tanpa menimbang","Timbang mana yang lebih penting untuk tujuan, & pertimbangkan apakah ada cara mendapat manfaatnya tanpa kerugiannya"],answer:2,explain:"Hasil bercampur adalah hal biasa. Keputusannya butuh menimbang, bukan label 'berhasil/gagal' yang cepat.",hint:"Timbang mana yang lebih penting, atau langsung labeli?"},
{n:67,type:"mcq",micro:"Iterasi & kesabaran",q:"Sikap yang membantu bertahan melalui banyak putaran:",options:["Melihat tiap putaran sebagai belajar, merayakan perbaikan kecil, & tidak menuntut lompatan besar tiap kali","Marah pada diri sendiri setiap kali hasilnya belum sempurna supaya lain kali kita lebih bersungguh-sungguh","Berhenti saja kalau percobaan pertama tidak langsung berhasil karena itu tandanya idenya kurang baik"],answer:0,explain:"Iterasi adalah maraton kecil-kecilan. Menghargai kemajuan bertahap menjaga semangat sampai hasilnya matang.",hint:"Rayakan perbaikan kecil, atau marah tiap belum sempurna?"},
{n:68,type:"mcq",micro:"Iterasi dalam kelompok yang tidak sabar",q:"Kelompokmu ingin 'langsung jadi' & enggan menguji versi kasar. Cara meyakinkan:",options:["Memaksa mereka menguji versi kasar tanpa menjelaskan alasannya supaya rapat tidak berlarut-larut","Tunjukkan bahwa satu uji cepat sekarang bisa mencegah pengerjaan ulang besar nanti, & usulkan putaran singkat berbatas waktu","Menyerah dan ikut membuat versi final tanpa uji, lalu berharap semuanya akan berjalan lancar nanti"],answer:1,explain:"Menghubungkan iterasi dengan menghindari kerja ulang & tenggat yang meleset sering lebih meyakinkan daripada sekadar 'ini cara yang benar'.",hint:"Tunjukkan manfaat menghindari kerja ulang, atau menyerah / memaksa?"},
{n:69,type:"mcq",micro:"Iterasi & ego",q:"Hambatan pribadi terbesar bagi iterasi sering...",options:["Kekurangan bahan","Terlalu banyak umpan balik","Rasa bahwa mengubah karya sendiri berarti mengakui versi sebelumnya 'salah', padahal itu wajar & bagian dari proses"],answer:2,explain:"Melepaskan gagasan 'versiku harus langsung benar' membebaskan kita memperbaiki tanpa merasa direndahkan.",hint:"Ego yang menganggap perubahan = kekalahan, atau kekurangan bahan?"},
{n:70,type:"tf",micro:"Iterasi bukan alasan menunda selamanya",q:"Benar atau Salah: 'Masih perlu satu putaran lagi' bisa menjadi alasan untuk tidak pernah menyelesaikan atau meluncurkan apa pun.",answer:true,explain:"Iterasi yang sehat punya titik 'cukup baik, luncurkan, perbaiki nanti berdasarkan pemakaian nyata'. Menunda tanpa henti demi kesempurnaan bukan iterasi, itu penghindaran.",hint:"Bisa jadi alasan menunda selamanya, atau selalu perlu satu putaran lagi?"},
{n:71,type:"mcq",micro:"Umpan balik yang bertentangan antar putaran",q:"Di putaran 2, penguji minta A. Di putaran 3, penguji baru minta kebalikan A. Sikap:",options:["Cari tahu apakah kedua kelompok penguji berbeda kebutuhannya, & pertimbangkan solusi yang melayani keduanya atau memilih satu target utama","Ubah bolak-balik mengikuti umpan balik yang terakhir datang supaya penguji terbaru selalu merasa puas","Abaikan semua umpan balik itu karena penguji yang berbeda pasti selalu memberikan pendapat yang berlawanan"],answer:0,explain:"Umpan balik bertentangan sering berarti penggunanya berbeda. Iterasi butuh menimbang, bukan hanya menuruti suara terakhir.",hint:"Selidiki perbedaan penguji, atau ikuti yang terakhir?"},
{n:72,type:"mcq",micro:"Mendokumentasikan pelajaran",q:"Di akhir sebuah proyek iteratif, hal berharga untuk ditulis:",options:["Tidak perlu menulis apa-apa, sebab proyeknya sudah selesai dan semua orang sudah tahu hasilnya","Daftar 'apa yang kami pelajari' & 'apa yang akan kami lakukan berbeda lain kali', supaya proyek berikutnya mulai lebih maju","Hanya hasil akhirnya saja, sedangkan proses dan pelajaran di tengah jalan tidak perlu dituliskan"],answer:1,explain:"Pelajaran yang dicatat menjadi 'titik awal' yang lebih tinggi untuk proyek berikutnya, sehingga kemajuan menumpuk antar proyek.",hint:"Catat pelajaran untuk proyek berikutnya, atau cukup hasil akhir?"},
{n:73,type:"mcq",micro:"Iterasi & rasa takut gagal",q:"Bagaimana budaya 'aman untuk gagal' membantu iterasi kelompok?",options:["Orang jadi ceroboh & tidak peduli lagi pada mutu karena merasa kesalahan apa pun akan dimaklumi","Tidak ada pengaruhnya sama sekali pada cara kelompok bekerja karena budaya tidak menentukan hasil","Orang berani mencoba ide berisiko & melaporkan masalah lebih awal, sehingga perbaikan datang lebih cepat"],answer:2,explain:"Kalau kegagalan dihukum, orang menyembunyikan masalah sampai membesar. Kalau kegagalan eksperimen diterima, masalah muncul & diperbaiki lebih dini.",hint:"Masalah dilaporkan lebih dini, atau orang jadi ceroboh?"},
{n:74,type:"mcq",micro:"Iterasi vs mengganti total",q:"Kadang lebih baik membuang versi sekarang & memulai ulang daripada terus memperbaikinya. Itu terjadi ketika...",options:["Masalah mendasarnya ada di fondasi/arah, bukan di detail, sehingga tambalan demi tambalan tidak akan pernah cukup","Ada satu bug kecil","Kamu bosan"],answer:0,explain:"Iterasi cocok untuk memperbaiki di atas fondasi yang benar. Kalau fondasinya salah, mulai ulang dengan pelajaran yang sudah didapat lebih hemat.",hint:"Masalah di fondasi/arah, atau satu bug kecil?"},
{n:75,type:"order",micro:"Retrospektif setelah proyek",q:"Urutkan langkah retrospektif kelompok setelah sebuah proyek.",items:["Kumpulkan semua orang & sepakati aturan: fokus perbaikan, bukan menyalahkan","Bahas: apa yang berjalan baik & perlu dipertahankan","Bahas: apa yang menyulitkan & kenapa (cari penyebab, bukan orang)","Sepakati 2-3 hal konkret yang akan diubah di proyek berikutnya & siapa yang mengingatkannya"],answer:[0,1,2,3],explain:"Aturan aman → yang baik → yang sulit & penyebabnya → komitmen perubahan. Berakhir pada tindakan spesifik, bukan sekadar curhat.",hint:"Membahas yang berjalan baik sebelum atau sesudah yang menyulitkan?"},
{n:76,type:"tf",micro:"Kemajuan tidak selalu lurus",q:"Benar atau Salah: Dalam proses iterasi yang panjang, wajar bila beberapa putaran terasa mundur atau tidak ada kemajuan sebelum akhirnya melompat maju.",answer:true,explain:"Kemajuan sering bergelombang: beberapa percobaan buntu, lalu satu temuan membuka jalan. Ketekunan melewati bagian datar itu penting.",hint:"Wajar ada bagian datar/mundur, atau kemajuan selalu lurus naik?"},
{n:77,type:"mcq",micro:"Menilai apakah iterasi berhasil secara keseluruhan",q:"Cara menilai apakah proses iterasi sebuah proyek berjalan sehat:",options:["Lihat apakah pembuatnya sudah kelelahan, sebab capek berarti iterasinya sudah dikerjakan dengan serius","Bandingkan versi awal & versi sekarang pada ukuran yang penting, & lihat apakah pelajaran tiap putaran benar-benar dipakai","Hitung saja berapa banyak versi yang sudah dibuat, karena makin banyak versi berarti makin sehat prosesnya"],answer:1,explain:"Banyak versi tidak berarti apa-apa kalau tidak ada perbaikan nyata. Yang penting: apakah hasilnya membaik & pelajaran diterapkan.",hint:"Perbaikan nyata & pelajaran dipakai, atau jumlah versi?"},
{n:78,type:"mcq",micro:"Iterasi & keputusan 'cukup'",q:"Siapa yang sebaiknya memutuskan bahwa iterasi sudah 'cukup' & saatnya menyelesaikan?",options:["Selalu orang yang paling perfeksionis, sebab dialah yang paling tahu kapan hasilnya sudah sempurna","Selalu orang yang paling ingin cepat selesai, sebab dialah yang paling peduli pada tenggat waktu","Disepakati bersama berdasarkan tujuan & tenggat, sering dengan masukan dari orang yang akan memakai hasilnya"],answer:2,explain:"Keputusan 'cukup' menyeimbangkan mutu, waktu, & kebutuhan. Diserahkan ke satu kutub (perfeksionis atau tergesa) sama-sama berisiko.",hint:"Disepakati berdasar tujuan & tenggat, atau ikut satu kutub?"},
{n:79,type:"mcq",micro:"Iterasi seumur hidup",q:"Menerapkan pola pikir iteratif pada diri sendiri berarti...",options:["Menganggap kebiasaan, keterampilan, & cara berpikir kita sebagai 'versi' yang bisa terus diperbaiki lewat refleksi & percobaan","Menganggap kepribadian & kemampuan kita tidak bisa berubah sama sekali sejak kita dilahirkan ke dunia","Terus-menerus merasa tidak puas dengan diri sendiri dan menuntut diri agar langsung menjadi sempurna"],answer:0,explain:"Melihat diri sebagai 'sedang dalam proses' (bukan 'sudah jadi' atau 'gagal permanen') membuat pertumbuhan pribadi terasa mungkin & terarah.",hint:"Diri sebagai versi yang bisa diperbaiki, atau tetap / selalu tidak puas?"},
{n:80,type:"open",micro:"Kapan berhenti & kapan mulai ulang",q:"Kamu sudah 5 putaran memperbaiki sebuah proyek. Jelaskan bagaimana kamu akan memutuskan di antara tiga pilihan: (1) menyelesaikan sekarang (cukup baik), (2) satu-dua putaran lagi, (3) membuang & memulai ulang dengan pelajaran yang sudah didapat. Beri kriteria konkret untuk masing-masing, lalu terapkan pada satu contoh nyata dari pengalamanmu.",explain:"Jawaban baik: kriteria untuk ketiga pilihan yang bisa dibedakan dengan jelas (terutama membedakan 'masalah di detail' vs 'masalah di fondasi'), lalu penerapan pada contoh nyata di mana keputusannya sesuai dengan kriteria yang ditulis, termasuk menyebut pelajaran apa yang dibawa kalau memilih memulai ulang.",hint:"Kunci membedakan (2) dan (3): apakah masalahnya bisa diperbaiki di atas fondasi yang ada, atau masalahnya justru fondasinya.",sample:"Kriteria untuk (1) menyelesaikan sekarang: hasil sudah memenuhi tujuan utama, putaran terakhir hanya memperbaiki hal-hal kecil yang tidak terlalu penting, tenggat dekat, & pengguna yang mencoba tidak menyebut masalah besar. Kriteria untuk (2) satu-dua putaran lagi: masih ada 1-2 masalah yang jelas & penting tapi bisa diperbaiki tanpa mengubah fondasi, & masih ada cukup waktu; tiap putaran sebelumnya masih menghasilkan perbaikan yang terasa. Kriteria untuk (3) memulai ulang: masalah terbesar ternyata ada di keputusan dasar (arah, bentuk, atau asumsi awal), sehingga tiap perbaikan hanya menambal & masalah yang sama muncul lagi dengan wajah berbeda; aku juga sudah tahu jelas apa yang akan kubuat berbeda dari nol. Contoh nyata: aku membuat aplikasi kartu hafalan dari kertas untuk belajar bahasa. Setelah 5 putaran, kartunya rapi tapi aku tetap malas memakainya. Masalahnya bukan di desain kartu (yang terus kuperbaiki), melainkan di keputusan dasar 'harus membawa tumpukan kartu ke mana-mana'. Aku memilih (3): memulai ulang dengan bentuk berbeda, daftar di buku saku kecil yang selalu kubawa, memakai pelajaran dari 5 putaran itu (kata sedikit per halaman, ada contoh kalimat, warna untuk yang sulit). Kalau masalahnya hanya 'hurufnya kekecilan', aku akan memilih (2)."},
{n:81,type:"mcq",micro:"Skenario: percobaan pertama gagal total",q:"Percobaan pertama proyekmu gagal sepenuhnya & kamu punya waktu 1 minggu lagi. Langkah terbaik:",options:["Ulangi persis yang sama seperti kemarin dengan harapan kali ini hasilnya akan berbeda dari sebelumnya","Lakukan retrospektif singkat (kenapa gagal), pilih 2 perbaikan terpenting, buat versi 2 secepatnya & uji lagi","Menyerah saja karena percobaan pertama sudah gagal sepenuhnya & waktu satu minggu pasti tidak cukup"],answer:1,explain:"Kegagalan pertama adalah data. Satu putaran perbaikan yang terarah dalam sisa waktu bisa mengubah hasil sepenuhnya.",hint:"Retrospektif lalu versi 2 terarah, atau menyerah / ulangi sama?"},
{n:82,type:"mcq",micro:"Skenario: tim menyalahkan satu orang",q:"Sebuah kesalahan menyebabkan proyek tersendat & tim mulai menyalahkan satu anggota. Sebagai bagian tim, sikapmu:",options:["Ikut menyalahkan agar tidak dianggap membelanya","Diam saja","Alihkan ke 'bagaimana sistem kerja kita membiarkan ini terjadi & apa yang bisa kita ubah', supaya semua belajar & yang bersangkutan tidak dikucilkan"],answer:2,explain:"Kesalahan satu orang sering menunjukkan celah dalam cara tim mengecek & saling mendukung. Fokus perbaikan sistem lebih berguna & lebih adil.",hint:"Alihkan ke perbaikan sistem, atau ikut menyalahkan / diam?"},
{n:83,type:"mcq",micro:"Skenario: versi baru lebih buruk",q:"Kamu semangat mengubah banyak hal di versi 4, tapi penguji jelas lebih menyukai versi 3. Langkah:",options:["Kembali ke versi 3, lalu terapkan perubahan versi 4 satu per satu untuk menemukan mana yang merugikan","Pertahankan versi 4 karena lebih baru & kamu sudah bekerja sangat keras untuk membuatnya selama ini","Ubah lebih banyak lagi di versi 5 sampai penguji akhirnya menyukainya, tanpa kembali ke versi sebelumnya"],answer:0,explain:"Karena banyak hal diubah sekaligus, kamu tidak tahu perubahan mana yang buruk. Kembali & uji satu per satu.",hint:"Kembali & uji perubahan satu per satu, atau pertahankan karena baru?"},
{n:84,type:"mcq",micro:"Skenario: guru menilai hanya hasil akhir",q:"Guru menilai proyek hanya dari hasil akhir, bukan prosesnya. Apakah iterasi masih berguna?",options:["Hanya berguna kalau guru memintanya secara khusus, sebab kalau tidak diminta tidak akan dinilai","Ya, karena proses iterasi hampir selalu menghasilkan hasil akhir yang lebih baik, yang tetap dinilai lebih tinggi","Tidak, kalau prosesnya tidak dinilai maka lebih baik langsung membuat versi final saja sekali jadi"],answer:1,explain:"Iterasi bukan demi 'poin proses', tapi demi mutu hasil. Hasil yang diperbaiki beberapa kali biasanya jelas lebih baik daripada draf pertama.",hint:"Iterasi memperbaiki hasil akhir juga, atau hanya berguna kalau dinilai?"},
{n:85,type:"tf",micro:"Iterasi & inovasi",q:"Benar atau Salah: Sebagian besar produk & ide inovatif lahir dari ilham sekali jadi, bukan dari putaran perbaikan bertahap.",answer:false,explain:"Sebaliknya, di balik hal yang tampak seperti terobosan mendadak biasanya ada bertahun-tahun percobaan, kegagalan, & perbaikan bertahap atas versi-versi sebelumnya.",hint:"Hasil banyak putaran, atau ilham sekali jadi?"},
{n:86,type:"mcq",micro:"Skenario: waktu untuk retrospektif dianggap buang-buang",q:"Anggota tim bilang 'ngapain rapat evaluasi, mending langsung kerja'. Tanggapan yang baik:",options:["Setuju saja dengan temanmu & lewati rapat evaluasi supaya waktu yang ada dipakai untuk bekerja lagi","Paksakan rapat evaluasi yang panjang tanpa tujuan hasil yang jelas supaya semua orang terpaksa ikut","Usulkan retrospektif singkat 10 menit yang berakhir dengan 2-3 perubahan konkret, tunjukkan bahwa itu menghemat kesalahan berulang"],answer:2,explain:"Retrospektif yang singkat & menghasilkan tindakan nyata membuktikan nilainya. Retrospektif yang bertele-tele tanpa hasil memang layak dikeluhkan.",hint:"Retrospektif singkat & menghasilkan tindakan, atau lewati / rapat panjang kosong?"},
{n:87,type:"mcq",micro:"Skenario: banyak ide perbaikan, sedikit waktu",q:"Kamu punya 15 ide perbaikan & waktu untuk 3. Cara memilih:",options:["Pilih yang paling berdampak pada tujuan & paling cepat dikerjakan; simpan sisanya di daftar","Pilih yang paling mudah dikerjakan saja tanpa memikirkan seberapa besar dampaknya bagi tujuan proyek","Coba kerjakan ke-15 perbaikan itu dengan terburu-buru walau waktunya hanya cukup untuk tiga di antaranya"],answer:0,explain:"Prioritaskan berdasarkan dampak & biaya. Daftar sisa menjaga ide lain tidak hilang untuk putaran mendatang.",hint:"Dampak tinggi + cepat, atau termudah / semua sekaligus?"},
{n:88,type:"mcq",micro:"Skenario: iterasi kebiasaan gagal seminggu",q:"Kamu mencoba kebiasaan belajar baru selama seminggu & sering meleset. Sikap iteratif:",options:["Ulangi rencana yang sama persis minggu depan dengan lebih bersemangat supaya hasilnya bisa lebih baik","Tinjau: bagian mana yang gagal & kenapa (terlalu ambisius? waktu salah?), sesuaikan jadi lebih kecil/realistis, coba minggu berikutnya","Simpulkan bahwa kamu memang 'tidak disiplin' dan berhenti mencoba kebiasaan belajar yang baru itu"],answer:1,explain:"Kebiasaan yang gagal biasanya karena rencananya tidak cocok, bukan karena orangnya. Iterasi menyesuaikan rencana, bukan menghukum diri.",hint:"Sesuaikan rencana jadi realistis, atau simpulkan tidak disiplin?"},
{n:89,type:"mcq",micro:"Skenario: sukses awal membuat malas iterasi",q:"Versi pertama proyekmu langsung dipuji. Apakah kamu tetap perlu menguji & memperbaiki?",options:["Tidak perlu, sebab kalau versi pertama sudah dipuji berarti proyek itu sudah selesai dan sempurna","Hanya kalau ada orang yang mengeluh, sebab kalau tidak ada keluhan berarti tidak ada masalah apa pun","Ya, pujian awal bisa menyembunyikan masalah yang baru muncul saat dipakai lebih luas atau lebih lama"],answer:2,explain:"Kesan pertama yang baik belum tentu bertahan. Uji dengan pemakaian nyata & beragam pengguna tetap berharga.",hint:"Tetap uji karena pujian bisa menyembunyikan masalah, atau berhenti setelah dipuji?"},
{n:90,type:"order",micro:"Proyek: perbaiki lewat 3 putaran",q:"Urutkan langkah proyek 'perbaiki satu hal lewat tiga putaran dalam dua minggu'.",items:["Tetapkan tujuan & catat ukuran titik awal versi sekarang","Putaran 1: ubah satu hal, uji, catat hasil vs titik awal","Putaran 2: berdasar hasil, ubah satu hal lagi (atau kembalikan yang buruk), uji","Putaran 3: perbaikan terakhir, uji, bandingkan versi akhir dengan titik awal & tulis pelajaran"],answer:[0,1,2,3],explain:"Titik awal → tiga putaran ubah-satu-hal-dan-uji → bandingkan awal vs akhir + pelajaran. Perbandingan dengan titik awal menunjukkan kemajuan nyata.",hint:"Mencatat ukuran titik awal di langkah pertama atau terakhir?"},
{n:91,type:"mcq",micro:"Skenario: iterasi mengungkap tujuan yang salah",q:"Di putaran ke-3, kamu sadar bahwa hal yang kamu perbaiki bukan yang paling penting bagi pengguna. Sikap:",options:["Hentikan iterasi di jalur ini, definisikan ulang tujuan berdasar temuan, & mulai putaran baru ke arah yang benar","Lanjutkan saja memperbaiki jalur lama itu karena sudah terlanjur menghabiskan banyak waktu dan tenaga","Selesaikan apa adanya tanpa mengubah arah karena mengubah tujuan di tengah jalan itu membuang waktu"],answer:0,explain:"Menemukan bahwa arahnya kurang tepat adalah hasil berharga dari iterasi. Berani berbelok lebih baik daripada memoles jalan yang salah.",hint:"Definisikan ulang tujuan & belok, atau lanjut jalur lama?"},
{n:92,type:"tf",micro:"Iterasi & kesabaran orang lain",q:"Benar atau Salah: Saat orang lain menunggu hasil kerja iteratifmu, penting mengomunikasikan bahwa ini proses bertahap & menunjukkan kemajuan tiap putaran, bukan menghilang sampai 'sempurna'.",answer:true,explain:"Menunjukkan versi-versi antara menjaga kepercayaan, mengundang umpan balik dini, & mencegah kejutan besar di akhir.",hint:"Tunjukkan kemajuan tiap putaran, atau menghilang sampai sempurna?"},
{n:93,type:"mcq",micro:"Skenario: dua jalur perbaikan",q:"Ada dua cara berbeda memperbaiki proyekmu & kamu tidak yakin mana yang lebih baik. Pendekatan iteratif:",options:["Kerjakan keduanya sepenuhnya sampai akhir secara bersamaan, lalu bandingkan setelah semuanya selesai","Coba masing-masing dalam versi kecil, bandingkan hasilnya, lalu lanjutkan dengan yang lebih menjanjikan","Pilih berdasarkan tebakan saja & jangan pernah menengok cara yang lain supaya tidak jadi ragu-ragu"],answer:1,explain:"Uji kecil kedua jalur memberi bukti untuk memilih, jauh lebih murah daripada mengerjakan keduanya penuh atau menebak.",hint:"Uji kecil kedua jalur & bandingkan, atau tebak / kerjakan keduanya penuh?"},
{n:94,type:"mcq",micro:"Skenario: kegagalan berisiko",q:"Idemu melibatkan percobaan yang bisa membahayakan keselamatan atau merusak barang milik sekolah. Pendekatan yang tepat:",options:["Coba diam-diam saja lalu lihat apa yang terjadi, sebab izin hanya akan membuat idemu dilarang","Batalkan semua ide yang tidak seratus persen aman tanpa mencari cara yang lebih aman untuk mengujinya","Jangan pakai 'coba dulu, lihat hasilnya', rancang hati-hati, minta izin & pengawasan, uji dengan pengaman & skala paling kecil yang aman"],answer:2,explain:"Iterasi cepat cocok untuk eksperimen yang aman. Untuk yang berisiko, kehati-hatian, izin, & pengaman datang lebih dulu, tapi banyak ide berisiko punya versi aman yang bisa diuji.",hint:"Rancang hati-hati dengan izin & pengaman, atau coba diam-diam?"},
{n:95,type:"tf",micro:"Iterasi mengubah hubungan dengan kegagalan",q:"Benar atau Salah: Terbiasa beriterasi mengubah cara kita memandang kegagalan, dari sesuatu yang memalukan & harus dihindari, menjadi bagian normal & berguna dari membuat sesuatu yang baik.",answer:true,explain:"Ketika 'gagal' berarti 'menemukan satu hal yang perlu diperbaiki', ia kehilangan sengatnya & menjadi bahan bakar kemajuan.",hint:"Mengubah kegagalan jadi bagian normal & berguna, atau tetap memalukan?"},
{n:96,type:"mcq",micro:"Skenario: menutup proyek dengan pelajaran",q:"Proyek iteratifmu selesai. Selain menyerahkan hasil, hal berharga yang kamu lakukan:",options:["Menulis ringkasan: versi awal vs akhir, keputusan penting tiap putaran, & 3 pelajaran untuk proyek berikutnya","Langsung melupakan proyek itu & mulai mengerjakan hal baru supaya pikiran tidak terbebani lagi","Hanya menyimpan versi akhir proyek saja tanpa catatan apa pun tentang proses dan pelajaran yang didapat"],answer:0,explain:"Ringkasan pelajaran membuat proyek berikutnya mulai dari titik yang lebih tinggi. Ini iterasi antar proyek, bukan hanya di dalamnya.",hint:"Tulis ringkasan pelajaran, atau lupakan / simpan hasil saja?"},
{n:97,type:"mcq",micro:"Menilai kualitas prosesmu",q:"Tanda kamu beriterasi dengan sehat:",options:["Kamu tidak pernah mengubah versi pertama karena yakin versi itu sudah yang terbaik dari semuanya","Kamu punya tujuan & ukuran, mengubah sedikit tiap putaran, menguji dengan bukti nyata, tahu kapan cukup, & pelajaranmu terpakai","Kamu membuat banyak versi tetapi tidak pernah mengukur atau menguji apakah versinya benar-benar membaik"],answer:1,explain:"Proses yang sehat: terarah, kecil per langkah, berbasis bukti, punya titik berhenti, & menumpuk pelajaran.",hint:"Terarah-kecil-berbukti-tahu cukup, atau banyak versi tanpa ukur?"},
{n:98,type:"mcq",micro:"Iterasi di luar sekolah",q:"Pola 'coba, tinjau, perbaiki, ulangi' berguna untuk...",options:["Hanya proyek teknik dan pembuatan produk saja, sedangkan urusan pribadi harus dikerjakan dengan cara lain","Tidak berguna di kehidupan sehari-hari karena hanya cocok untuk laboratorium dan pekerjaan di pabrik","Hampir semua hal: hubungan (menyesuaikan cara berkomunikasi), keuangan pribadi (menyesuaikan anggaran), kesehatan, keterampilan, kebiasaan"],answer:2,explain:"Iterasi adalah cara belajar dari kenyataan. Ia berlaku di mana pun ada tindakan yang bisa dinilai & disesuaikan.",hint:"Berguna untuk banyak bidang hidup, atau hanya produk?"},
{n:99,type:"mcq",micro:"Inti keterampilan",q:"Inti dari 'uji coba, gagal, perbaiki':",options:["Perlakukan tiap versi sebagai percobaan, pelajari dari hasil nyatanya (termasuk kegagalan), ubah sedikit berdasar bukti, & ulangi sampai cukup baik","Rencanakan dengan sempurna sekali saja lalu jalankan tanpa perubahan apa pun sampai proyek benar-benar selesai","Terus mengubah hasilnya tanpa pernah mengukur apa pun atau menetapkan tujuan yang jelas lebih dulu"],answer:0,explain:"Percobaan → belajar dari kenyataan → perbaikan kecil berbasis bukti → ulangi, dengan titik 'cukup baik'. Kegagalan adalah bahan bakar, bukan vonis.",hint:"Percobaan-belajar-perbaiki berbukti-ulangi, atau rencana sempurna sekali?"},
{n:100,type:"open",micro:"Kapstone: sistem perbaikan pribadi",q:"Rancang 'sistem perbaikan' pribadi untuk satu bidang hidupmu (belajar, olahraga, hobi, hubungan, keuangan). Sertakan: (a) tujuan & 1-2 ukuran, (b) seberapa sering kamu meninjau (harian/mingguan), (c) format tinjauan singkatmu (pertanyaan yang kamu tanyakan ke diri sendiri), (d) aturan agar kamu tidak berhenti saat gagal & tidak memperbaiki berlebihan, (e) bagaimana kamu menyimpan pelajaran, (f) cara kamu tahu setelah 2 bulan apakah sistem ini membantu.",explain:"Jawaban baik: tujuan dengan ukuran yang bisa dicatat, jadwal tinjauan yang realistis, pertanyaan tinjauan yang menggali penyebab & fokus berikutnya, aturan konkret untuk kedua jebakan (berhenti saat gagal & over-iterating), cara menyimpan pelajaran yang nyata, & kriteria evaluasi 2 bulan yang bisa diperiksa, termasuk kesediaan mengiterasi sistemnya sendiri bila tidak membantu.",hint:"Bagian (d) yang paling penting & sering lemah, tulis aturan spesifik, bukan 'aku akan tetap semangat' dan 'aku akan tahu kapan berhenti'.",sample:"Bidang: keterampilan menggambar. (a) Tujuan: bisa menggambar wajah dengan proporsi yang lebih tepat. Ukuran: (1) skor proporsi sendiri 1-5 pada gambar mingguan (dibandingkan foto acuan), (2) jumlah hari berlatih minimal 10 menit per minggu. (b) Tinjauan: mingguan, tiap Minggu malam, 10 menit. (c) Format tinjauan, aku tanya: 'Bagian mana dari gambar minggu ini yang paling meleset? Apa satu hal teknis yang mau kupelajari/latih minggu depan? Apakah latihan kemarin terasa terlalu berat atau pas? Adakah bagian yang sudah membaik & perlu kupertahankan?' (d) Aturan anti-berhenti & anti-berlebihan: kalau seminggu hasilnya jelek, aku tidak boleh menyimpulkan 'aku tidak berbakat', aku hanya boleh mengganti satu hal di rencana latihan; kalau tiga minggu berturut-turut skorku sudah 4-5 & aku masih mengutak-atik detail kecil, aku pindah ke sub-keterampilan berikutnya (mis. bayangan) alih-alih terus di proporsi. (e) Menyimpan pelajaran: buku sketsa dengan satu halaman 'catatan' tiap minggu berisi 'yang kupelajari' & 'fokus minggu depan', plus menyimpan semua gambar mingguan berurutan supaya kemajuan terlihat. (f) Menilai setelah 2 bulan: aku bandingkan gambar minggu 1 & minggu 8 berdampingan, lihat tren skor proporsi (harusnya naik), & cek konsistensi latihan (berapa minggu mencapai target hari). Kalau skor naik & aku berlatih minimal 6 dari 8 minggu, sistem ini membantu & kulanjutkan. Kalau tidak, aku tinjau bagian mana dari sistem yang tidak jalan, mungkin tinjauannya terlalu jarang atau ukurannya kurang tepat, dan aku iterasi sistemnya sendiri."},
];
